invisible(f())
t <- numeric(20)
for (i in seq_len(20)) { t0 <- Sys.time(); z <- f(); t[i] <- as.numeric(difftime(Sys.time(), t0, units="secs")) }
cat(sprintf("r_ms %.17g\n", median(t)*1000)); cat(normalize(z), "\n")

